// @vitest-environment node
import { describe, expect, it } from 'vitest'
import { experimental_AstroContainer as AstroContainer } from 'astro/container'
import { load as cheerioLoad } from 'cheerio'
import Button from '@/components/controls/Button.astro'

describe('spike', () => {
  it('renders Button via Container API', async () => {
    const container = await AstroContainer.create()
    const html = await container.renderToString(Button, {
      props: { El: 'a', href: '/foo' },
      slots: { default: 'Click' },
    })
    const $ = cheerioLoad(html)
    expect($('a[href="/foo"]').text()).toContain('Click')
  })
})

// @vitest-environment node
import { describe, expect, it } from 'vitest'
import { experimental_AstroContainer as AstroContainer } from 'astro/container'
import { load as cheerioLoad } from 'cheerio'
import NewsletterCard from '@/components/blocks/NewsletterCard.astro'

describe('spike-newsletter', () => {
  it('renders NewsletterCard general', async () => {
    const container = await AstroContainer.create()
    const html = await container.renderToString(NewsletterCard, {
      props: { description: 'Hallo', topic: 'general' },
    })
    const $ = cheerioLoad(html)
    console.error('HTML LEN', html.length)
    console.error('HAS H3:', $('h3').text())
    console.error('SNIPPET:', html.slice(0, 500))
    expect($('h3').text()).toContain('Bleib')
  })
})

