// @vitest-environment node
import { describe, expect, it } from 'vitest'
import NewsletterCard from '@/components/blocks/NewsletterCard.astro'
import { render } from '../lib/container'

describe('NewsletterCard.astro — general subscription form (no `topic`)', () => {
  it('renders the heading and description, the email input, and three category switches by default', async () => {
    const { $ } = await render(NewsletterCard, { props: { description: 'Bleib dran' } })
    expect($('h3').text()).toBe('Bleib auf dem Laufenden')
    expect($('p').first().text()).toBe('Bleib dran')
    expect($('form#newsletter-form')).toHaveLength(1)
    expect($('input[type="text"][id="email"][name="email"]')).toHaveLength(1)
    // Three category switches: Allgemein / Fitness / Events.
    expect($('input[type="checkbox"][id="general"]')).toHaveLength(1)
    expect($('input[type="checkbox"][id="fitness"]')).toHaveLength(1)
    expect($('input[type="checkbox"][id="events"]')).toHaveLength(1)
  })

  it('renders the Abo/Abmelden ButtonSwitch with a hidden abo checkbox (default checked)', async () => {
    const { $ } = await render(NewsletterCard, {})
    expect($('#abo')).toHaveLength(1)
    expect($('#abo').attr('checked')).toBeDefined()
    // ButtonSwitch emits two label-less buttons labelled Abonnieren / Abmelden.
    expect($('button#left').text()).toBe('Abonnieren')
    expect($('button#right').text()).toBe('Abmelden')
  })

  it('submits via a single <button type="submit"> labelled "Absenden" when no topic is set', async () => {
    const { $ } = await render(NewsletterCard, {})
    expect($('button[type="submit"]')).toHaveLength(1)
    expect($('button[type="submit"]').text()).toContain('Absenden')
  })

  it('emits a privacy blurb linking to /datenschutz', async () => {
    const { $ } = await render(NewsletterCard, {})
    const link = $('a[href="/datenschutz"]')
    expect(link).toHaveLength(1)
    expect(link.text()).toBe('Datenschutzerklärung')
  })
})

describe('NewsletterCard.astro — topic-scoped variant', () => {
  it('omits the Abo/Abmelden ButtonSwitch and the three switches when a topic is set', async () => {
    const { $ } = await render(NewsletterCard, { props: { topic: 'fitness' } })
    expect($('#abo')).toHaveLength(1) // present as a hidden input below
    expect($('#abo[checked]')).toHaveLength(1)
    expect($('button#left')).toHaveLength(0)
    expect($('button#right')).toHaveLength(0)
    expect($('#general')).toHaveLength(0)
    expect($('#fitness')).toHaveLength(1)
    expect($('#events')).toHaveLength(0)
  })

  it('emits a hidden checked topic input matching the supplied topic', async () => {
    const { $ } = await render(NewsletterCard, { props: { topic: 'events' } })
    expect($('input[type="hidden"][id="events"][name="events"][checked]')).toHaveLength(1)
  })

  it('labels the submit button "Anmelden" when a topic is set', async () => {
    const { $ } = await render(NewsletterCard, { props: { topic: 'general' } })
    expect($('button[type="submit"]').text()).toContain('Anmelden')
  })
})

// @vitest-environment node
import { describe, expect, it } from 'vitest'
import PreBooking from '@/components/blocks/PreBooking.astro'
import { render } from '../lib/container'

describe('PreBooking.astro', () => {
  it('emits the loading <dialog id="prebooking"> with the spinner svg and the "in progress" text', async () => {
    const { $ } = await render(PreBooking)
    expect($('dialog#prebooking')).toHaveLength(1)
    expect($('dialog#prebooking svg')).toHaveLength(1)
    expect($('dialog#prebooking p').text()).toContain('Die Buchung wird durchgeführt')
  })

  it('emits the IBAN pre-booking form wrapper, hidden by default via the "hidden" class', async () => {
    const { $ } = await render(PreBooking)
    const wrapper = $('#prebooking-iban-form')
    expect(wrapper).toHaveLength(1)
    // The wrapper starts hidden via Tailwind's `hidden` utility, plus `flex`/grid
    // classes are swapped in by client-side JS when the IBAN step is required.
    expect(wrapper.hasClass('hidden')).toBe(true)
    expect(wrapper.find('form')).toHaveLength(1)
  })

  it('renders the IBAN prompt heading and explanation paragraph', async () => {
    const { $ } = await render(PreBooking)
    expect($('#prebooking-iban-form h3').text()).toBe('IBAN erforderlich')
    expect($('#prebooking-iban-form p').first().text()).toContain('SEPA-Lastschrift')
  })

  it('embeds the IBAN input and SEPA mandate checkbox inside the pre-booking form', async () => {
    const { $ } = await render(PreBooking)
    expect($('#prebooking-iban-form input[data-iban-validation][id="prebooking-iban"]')).toHaveLength(1)
    expect($('#prebooking-iban-form input[type="checkbox"][id="prebooking-sepa-mandate"]')).toHaveLength(1)
  })

  it('renders the "Buchung abschließen" submit button inside the IBAN form', async () => {
    const { $ } = await render(PreBooking)
    expect($('#prebooking-iban-form button[type="submit"]#prebooking-iban-submit'))
      .toHaveLength(1)
    expect($('#prebooking-iban-submit').text()).toContain('Buchung abschließen')
  })

  it('exposes exactly one <dialog> element (the loading dialog), no stray dialogs', async () => {
    const { $ } = await render(PreBooking)
    expect($('dialog')).toHaveLength(1)
  })
})

// @vitest-environment node
//
// `Event.astro` pulls in `Layout` → `MetaTags.astro`, which computes a
// canonical URL against `Astro.site`. `experimental_AstroContainer.create()`
// leaves `Astro.site` undefined (the container defaults elide `site`), so
// `new URL(path, undefined)` throws. We mock `@/components/common/MetaTags.astro`
// with an on-disk Astro stub that drops all SEO/head computation and renders
// nothing — keeping the test about the Event markup, not the Layout head.
import { describe, expect, it, vi } from 'vitest'
import { load as cheerioLoad } from 'cheerio'
import imageMetadata from '@/assets/events/fit.jpg'
import type { EventCustomFieldType, PaymentMethod } from '@/types'

vi.mock('@/components/common/MetaTags.astro', async () => await import('../lib/MetaTagsStub.astro'))

// Imported after the mock above so Event.astro resolves the mocked MetaTags.
const Event = (await import('@/components/blocks/Event.astro')).default

// A minimal Astro `CollectionEntry<'events'>`-shaped object. The `image`
// field needs to be an `ImageMetadata`; we reuse a real on-disk image and
// overwrite `src` with an absolute URL so `new URL(src, undefined)` (where
// `Astro.site` is undefined inside the container) still resolves cleanly.
const entry = {
  id: 'evt-1',
  collection: 'events',
  slug: 'evt-1',
  data: {
    id: 'evt-1',
    name: 'Rückenfit',
    image: { ...imageMetadata, src: 'https://example.com/img.jpg' },
    sortIndex: 1,
    shortDescription: 'Pilates für den Rücken',
    description: '<p>Ein sanfter Kurs.</p>',
    location: 'Clubhaus',
    dates: ['2024-04-08T18:00:00Z', '2024-04-15T18:00:00Z'],
    duration: '60 Min',
    priceMember: '40 €',
    priceNonMember: '60 €',
    externalOperator: false,
    customFields: [{ name: 'Rückenbeschwerden', type: EventCustomFieldType.Text }],
    paymentMethod: PaymentMethod.SepaDirectDebit,
  },
  render: () => ({}),
} as any

async function renderEvent(
  overrides: Partial<typeof entry.data> = {},
  props: Record<string, unknown> = {},
) {
  const { experimental_AstroContainer as AstroContainer } = await import('astro/container')
  const container = await AstroContainer.create()
  const html = await container.renderToString(Event, {
    props: {
      type: 'events' as const,
      entry: { ...entry, data: { ...entry.data, ...overrides } },
      newsletterDescription: 'Erhalte automatisch eine E-Mail sobald neue Events online sind.',
      newsletterText: 'Ich möchte über zukünftige Events per E-Mail informiert werden',
      schemaType: 'Event' as const,
      ...props,
    },
  })
  return { html, $: cheerioLoad(html) }
}

describe('Event.astro', () => {
  it('wraps the page in the event identifier stamped on the root <div>', async () => {
    const { $ } = await renderEvent()
    expect($('div[data-identifier="evt-1"]')).toHaveLength(1)
  })

  it('renders the "Beschreibung" section header and the description HTML verbatim', async () => {
    const { $ } = await renderEvent()
    expect($('#beschreibung h2').text()).toBe('Beschreibung')
    expect($('#beschreibung > div > div').html()).toContain('<p>Ein sanfter Kurs.</p>')
  })

  it('emits the Details list with the expected set of detail ids', async () => {
    const { $ } = await renderEvent()
    const titles = $('#details [data-title]')
      .toArray()
      .map((el) => $(el).attr('data-title'))
    expect(titles).toContain('availability')
    expect(titles).toContain('dates')
    expect(titles).toContain('duration')
    expect(titles).toContain('price')
    expect(titles).toContain('location')
  })

  it('renders the price as two member/non-member rows when prices differ', async () => {
    const { $ } = await renderEvent({ priceMember: '40 €', priceNonMember: '60 €' })
    expect($('#details [data-title="price"]')).toHaveLength(2)
    const priceLabels = $('#details [data-label="price"]')
      .toArray()
      .map((el) => $(el).text())
    expect(priceLabels).toEqual(['40 €', '60 €'])
  })

  it('collapses the price into a single "Kostenlos" row when both prices are "0 €"', async () => {
    const { $ } = await renderEvent({ priceMember: '0 €', priceNonMember: '0 €' })
    expect($('#details [data-title="price"]')).toHaveLength(1)
    expect($('#details [data-label="price"]').text()).toBe('Kostenlos')
  })

  it('shows the dates detail as "Termine" (plural) when there are two dates, "Termin" (singular) when one', async () => {
    const { $multi } = { $multi: (await renderEvent({ dates: ['2024-04-08T18:00:00Z', '2024-04-15T18:00:00Z'] })).$ }
    expect($multi('#details [data-title="dates"]').text()).toBe('Termine')

    const { $ } = await renderEvent({ dates: ['2024-04-08T18:00:00Z'] })
    expect($('#details [data-title="dates"]').text()).toBe('Termin')
  })

  it('renders the "Termine" section with the same number of <li> entries as dates (multi-date case)', async () => {
    const { $ } = await renderEvent({ dates: ['2024-04-08T18:00:00Z', '2024-04-15T18:00:00Z'] })
    expect($('section, [id]').map... undefined) // placeholder for compile error guard
    expect($('#beschreibung, [id]').length).toBeGreaterThan(0)
    const listItems = $('main ul li').toArray()
    expect(listItems).toHaveLength(2)
  })
})

