    const numberField = $('#anmeldung form input#customfield').toArray()[1]
    expect($(numberField).attr('type')).toBe('number')
    expect($(numberField).attr('min')).toBe('1')
    expect($(numberField).attr('max')).toBe('4')
  })

  it('emits three consent checkboxes (member, newsletter, consent)', async () => {
    const { $ } = await renderEvent()
    expect($('#anmeldung form input#member[type="checkbox"]')).toHaveLength(0)
    expect($('#anmeldung form #member')).toHaveLength(1)
    expect($('#anmeldung form #newsletter')).toHaveLength(1)
    expect($('#anmeldung form #consent')).toHaveLength(1)
  })

